const uint32_t save_config_area = 0x0801f800;
config_t config;

static uint32_t checksum(const void *start, size_t len)
{
  uint32_t *p = (uint32_t*)start;
  uint32_t *tail = (uint32_t*)((char*)start + len);
  uint32_t value = len;
  while (p < tail)
    value ^= *p++;
  return value;
}

void flash_erase_page_sim(void) { memset(fake_flash, 0xFF, sizeof fake_flash); }

void flash_program_half_word_sim(uint32_t address, uint16_t data)
{
  fake_flash[address - save_config_area + 0] = data & 0xff;
  fake_flash[address - save_config_area + 1] = data >> 8;
}

